const ABILITY_GROUPS={"表演":["歌藝","演技","舞蹈","主持","聲線","鏡頭感","肢體表現"],"創作":["創作","作詞","作曲","編劇","樂器","靈感"],"形象":["外貌","氣質","時尚","儀態","親和力"],"社交與知識":["口才","社交","學識"]};
const ABILITIES=Object.values(ABILITY_GROUPS).flat();
const ACTIONS={
vocal:{group:"訓練",icon:"♫",label:"聲樂基礎課",short:"聲樂課",note:"歌藝為主，聲線為輔",type:"train",gains:[["歌藝",4,8],["聲線",1,3]],fatigue:8,stamina:8,cost:800},
acting:{group:"訓練",icon:"🎬",label:"新人表演課",short:"表演課",note:"演技、鏡頭感與肢體表現",type:"train",gains:[["演技",4,8],["鏡頭感",1,3],["肢體表現",1,2]],fatigue:9,stamina:9,cost:900},
dance:{group:"訓練",icon:"♬",label:"舞蹈基礎課",short:"舞蹈課",note:"舞蹈為主，肢體表現為輔",type:"train",gains:[["舞蹈",4,8],["肢體表現",1,3]],fatigue:11,stamina:11,cost:1000},
speech:{group:"訓練",icon:"🎙",label:"主持口條課",short:"口條課",note:"口才為主，主持為輔",type:"train",gains:[["口才",4,8],["主持",1,3]],fatigue:7,stamina:7,cost:700},
creation:{group:"訓練",icon:"✦",label:"創意開發課",short:"創意課",note:"創作與靈感訓練",type:"train",gains:[["創作",4,8],["靈感",1,3]],fatigue:7,stamina:7,cost:650},
songwriting:{group:"訓練",icon:"🎼",label:"詞曲創作課",short:"詞曲課",note:"作詞、作曲與樂器",type:"train",gains:[["作詞",3,7],["作曲",3,7],["樂器",1,3]],fatigue:9,stamina:9,cost:950},
script:{group:"訓練",icon:"✎",label:"劇本寫作課",short:"編劇課",note:"編劇為主，學識為輔",type:"train",gains:[["編劇",4,8],["學識",1,3]],fatigue:7,stamina:7,cost:650},
image:{group:"訓練",icon:"◇",label:"形象儀態課",short:"儀態課",note:"氣質、儀態與親和力",type:"train",gains:[["氣質",3,6],["儀態",3,6],["親和力",1,3]],fatigue:6,stamina:6,cost:750},
networking:{group:"訓練",icon:"☕",label:"社交應對課",short:"社交課",note:"社交與親和力訓練",type:"train",gains:[["社交",4,8],["親和力",1,3]],fatigue:6,stamina:6,cost:500},
audition:{group:"工作",icon:"★",label:"新人廣告試鏡",short:"廣告試鏡",note:"鏡頭感、親和力與口才",type:"work",fatigue:13,stamina:13,cost:300},
adshoot:{group:"工作",icon:"🎥",label:"晨露汽水廣告拍攝",short:"廣告拍攝",note:"合約通告・共需完成 3 次拍攝",type:"job",fatigue:18,stamina:18,cost:0},
street:{group:"工作",icon:"🎸",label:"街頭演出",short:"街頭演出",note:"賺取小費並累積實戰曝光",type:"work",fatigue:12,stamina:12,cost:0},
free:{group:"生活",icon:"☀",label:"自由活動",short:"自由活動",note:"探索星望市，可能遇見新人物",type:"life",fatigue:3,stamina:4,cost:300},
styling:{group:"生活",icon:"✧",label:"造型研究",short:"造型研究",note:"提升時尚與外貌管理",type:"life",gains:[["時尚",3,6],["外貌",1,2]],fatigue:3,stamina:3,cost:600},
study:{group:"生活",icon:"📖",label:"在家研究",short:"在家研究",note:"提升學識與創作靈感",type:"life",gains:[["學識",3,6],["靈感",1,2]],fatigue:2,stamina:2,cost:0},
rest:{group:"休息",icon:"☁",label:"在家休息",short:"休息",note:"恢復體力並降低疲勞",type:"rest",fatigue:-18,stamina:-24,cost:0},
agency_interview:{group:"工作",icon:"◆",label:"經紀公司面談",short:"公司面談",note:"重要行程・不收取費用",type:"interview",fatigue:10,stamina:10,cost:0}
};
const DAYS=["星期一","星期二","星期三","星期四","星期五","星期六","星期日"],SHORT=["一","二","三","四","五","六","日"];
const FOCUSES={growth:{icon:"✦",label:"能力成長",note:"本週所有能力成長額外＋1"},fame:{icon:"★",label:"增加曝光",note:"工作成功率與知名度收益提高"},people:{icon:"♡",label:"拓展人脈",note:"遇見新人物與建立關係的機會提高"}};
const NPCS={jiqing:{name:"紀晴",job:"廣播節目主持人",location:"星望廣播電臺",bio:"星望廣播電臺節目主持人。反應快、待人親切，對有潛力的新人很敏銳。",avatar:"紀"}};
const JOB={brand:"晨露飲品",title:"晨露汽水形象廣告",tagline:"清爽校園感・平面與短影音廣告",pay:12000,sessions:3,workDays:[0,1,2],requirements:[["鏡頭感",60],["親和力",50],["口才",40]]};
// 經紀公司資料：門檻、合約條件皆放在資料內，未來新增公司只需擴充此表，不需複製 UI 邏輯。
const AGENCIES={
 starlight:{
  id:"starlight",
  name:"星光藝能",
  shortName:"星光",
  type:"綜合型經紀公司",
  scale:"中型公司",
  description:"星望市歷史最久的中型經紀公司之一，戲劇、廣告與綜藝資源均衡，重視新人的長期栽培而非速成流量。",
  specialties:["戲劇","廣告","綜藝"],
  requirements:{contractReadiness:20,abilities:[["鏡頭感",60],["親和力",50]]},
  contract:{durationWeeks:104,commissionRate:.2,description:"兩年新人合約，公司提供資源培訓與通告引薦"}
 }
};
const AGENCY_LIST=Object.values(AGENCIES);
function initialState(){return{screen:"create",createStep:1,tab:"planner",appOpen:null,name:"",gender:"女性",customGender:"",stats:{},hidden:{},luck:0,rep:{業界評價:0,商業價值:0,話題度:0,爭議度:0,時尚影響力:0,國民度:0,路人緣:500,可信度:500},week:1,schedule:["vocal","acting","rest","audition","free","dance","rest"],lastSchedule:null,selectedDay:0,filter:"全部",focus:"growth",stamina:100,fatigue:0,mood:70,money:18000,fame:0,fans:0,contract:8,knownPeople:[],familiarNpcs:[],relationships:{},flags:[],runnerDay:0,runnerPhase:"",runnerResult:null,runnerDecision:null,weekResults:[],history:[],notice:"",drawerOpen:false,reward:null,mapLocation:null,jobStage:"available",jobRemaining:JOB.sessions,jobDeadline:3,jobNotice:"",selectedNpc:null,endingType:null,inheritChoice:true,hospitalSkipWeeks:0,agencyStatus:"unsigned",selectedAgencyId:null,agencyApplications:{},agencyInterview:null,agencyOffer:null,currentAgencyId:null,agencySignedWeek:null,agencyContractEndWeek:null}}
let state=initialState();
const app=document.querySelector("#app"),random=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const esc=v=>String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const money=n=>`$${Math.max(0,n).toLocaleString("zh-TW")}`;
const width=n=>Math.max(.35,Math.min(100,n/10));
const HIDDEN_TRAITS=["幽默","共情","洞察","膽識","品德","自律","野心","抗壓"];
// 成功率一律只顯示文字提示，不得外露精確百分比（規則 8）。
function successRateLabel(chance){if(chance<15)return"幾乎不可能";if(chance<30)return"希望渺茫";if(chance<50)return"值得一試";if(chance<75)return"勝算不錯";return"十拿九穩"}
function yearOf(){return Math.min(5,Math.ceil(state.week/52))}
function weekInYear(){return((state.week-1)%52)+1}
function rollStats(){
 state.stats=Object.fromEntries(ABILITIES.map(n=>[n,random(0,150)]));
 render()
}
function initializeHiddenStats(){
 if(Object.keys(state.hidden).length)return;
 state.hidden=Object.fromEntries(HIDDEN_TRAITS.map(n=>[n,350+random(1,100)+random(1,100)+random(1,100)]));
 state.luck=200+random(1,200)+random(1,200)+random(1,200);
}
function reroll(){rollStats()}
function render(){app.innerHTML=state.screen==="create"?createView():state.screen==="runner"?runnerView():state.screen==="summary"?summaryView():state.screen==="ending"?endingView():roomView();bind()}

function createView(){const best=Object.entries(state.stats).sort((a,b)=>b[1]-a[1]).slice(0,3);return `<main class="create-screen"><section class="create-art"><div class="logo">✦ 星途未定</div><img src="./assets/new-start-box.webp" alt="裝著表演用品的搬家紙箱"><div class="opening-copy"><span>序章｜18 歲的夏天</span><h1>帶著一箱夢想，<br>住進星望市。</h1><p>五年時間。沒有公司、沒有作品、沒有人脈。妳的明星人生，從這間小房間開始。</p></div></section><section class="create-form">${state.createStep===1?identityStep():statsStep(best)}</section></main>`}
function identityStep(){return `<div class="form-card"><div class="step-mark">STEP 1 / 2</div><h2>這位新人叫什麼名字？</h2><p>姓名與性別只影響稱呼和劇情，不會限制發展路線。</p><label><span>姓名／藝名</span><input id="player-name" maxlength="16" placeholder="輸入名字" value="${esc(state.name)}"></label><fieldset><legend>性別</legend><div class="gender-options">${["女性","男性","非二元","自訂"].map(g=>`<button class="${(g==="自訂"?!["女性","男性","非二元"].includes(state.gender):state.gender===g)?"active":""}" data-gender="${g}">${g}</button>`).join("")}</div></fieldset><label class="${["女性","男性","非二元"].includes(state.gender)?"hidden":""}"><span>自訂性別</span><input id="custom-gender" maxlength="20" value="${esc(state.customGender)}" placeholder="自由輸入"></label><button class="main-btn full" id="to-stats" ${state.name.trim()?"":"disabled"}>擲出初始能力 →</button></div>`}
function statsStep(best){return `<div class="form-card wide"><div class="roll-title"><div><div class="step-mark">STEP 2 / 2</div><h2>命運發了這副牌</h2><p>21 項固定公開能力各自隨機 0～150。不滿意就繼續骰，重骰次數不限。</p></div><button class="reroll" id="reroll">↻ 全部重骰</button></div><div class="best-tags">${best.map(([n,v],i)=>`<span>目前強項 ${i+1}<b>${n} ${v}</b></span>`).join("")}<em>所有能力進入遊戲後的上限皆為 1000</em></div><div class="rolled-grid">${Object.entries(ABILITY_GROUPS).map(([group,names])=>`<section><h3>${group}</h3>${names.map(n=>`<div class="mini-stat"><span>${n}</span><i><b style="width:${width(state.stats[n])}%"></b></i><strong>${state.stats[n]}</strong></div>`).join("")}</section>`).join("")}</div><div class="form-actions"><button class="back-btn" id="back">← 修改身分</button><button class="main-btn" id="start">就用這組，搬進星望市 →</button></div></div>`}

function playerIdentityLabel(){return state.currentAgencyId?`${esc(AGENCIES[state.currentAgencyId].name)}・旗下新人`:"未簽約新人"}
function roomView(){return `<main class="room-screen"><img class="room-bg" src="./assets/rookie-room.webp" alt="新人租屋處的工作桌"><header class="room-hud"><div class="player-chip"><div>${esc(state.name.slice(0,1))}</div><span><b>${esc(state.name)}</b><small>18 歲・${playerIdentityLabel()}</small></span></div><div class="hud-stats"><span>💰 <b>${money(state.money)}</b></span><span>★ 知名度 <b>${state.fame}</b></span><span>♡ 粉絲 <b>${state.fans}</b></span><span>☁ 疲勞 <b>${state.fatigue}</b></span></div></header><button class="desk-pin phone-pin" data-open-app="people"><i>1</i><b>手機</b><small>${state.knownPeople.length?"查看聯絡人":"新的城市，空白通訊錄"}</small></button><button class="desk-pin mail-pin" data-open-job><i>!</i><b>通告信封</b><small>新人廣告試鏡・本週截止</small></button><section class="tablet"><div class="tablet-camera"></div><div class="tablet-screen">${tabletHome()}${tabletDock()}</div></section>${state.appOpen?appWindow():""}</main>`}
function agencyHomeCard(){if(state.currentAgencyId){const agency=AGENCIES[state.currentAgencyId],remain=Math.max(0,state.agencyContractEndWeek-state.week+1);return `<button class="agency-entry" data-open-app="agency"><div><span>所屬經紀公司</span><b>${esc(agency.name)}</b></div><small>合約剩餘 <b>${remain}</b> 週・經紀抽成 <b>${Math.round(agency.contract.commissionRate*100)}%</b></small><small class="agency-entry-cta">查看公司資料 →</small></button>`}const eligible=AGENCY_LIST.filter(a=>checkAgencyEligibility(a).met).length;return `<button class="agency-entry" data-open-app="agency"><div><span>經紀公司</span><b>${state.contract}%</b></div><i><b style="width:${state.contract}%"></b></i><small>簽約準備度・目前身分：未簽約新人</small><small class="agency-entry-cta">可查看／投遞 ${eligible}／${AGENCY_LIST.length} 間公司 →</small></button>`}
function tabletHome(){return `<div class="tablet-home"><header><span>第 ${yearOf()} 年・第 ${weekInYear()} 週</span><b>${esc(state.name)}，早安！</b><small>今天先從安排這一週開始吧。</small></header>${agencyHomeCard()}<button class="next-action" data-open-app="planner"><span>下一步</span><b>安排第 ${state.week} 週行程</b><small>7 天尚未開始・預計支出 ${money(budget())}</small><i>→</i></button><div class="home-launchers"><button data-open-app="map"><b>⌖ 星望市地圖</b><small>選擇自由活動地點</small></button><button data-open-app="jobs"><b>▤ 通告中心</b><small>${state.jobStage==="available"?"1 份新邀約":state.jobStage==="active"?`剩餘 ${state.jobRemaining} 次拍攝`:"查看試鏡進度"}</small></button><button data-open-app="npc"><b>◈ 人物檔案</b><small>已認識人物的資料與關係</small></button></div><button class="retire-link" data-retire>結束這一輪，查看星途結算（測試用）→</button></div>`}
function tabletDock(){return `<nav class="tablet-dock">${[["planner","▦","行程"],["stats","◫","能力"],["people","♡","人際"],["log","≡","紀錄"]].map(([id,icon,label])=>`<button data-open-app="${id}"><i>${icon}</i>${label}</button>`).join("")}</nav>`}
function appWindow(){const meta={planner:["▦","行程與工作","安排七天行程、策略與預算"],stats:["◫","能力資料","檢視 21 項公開能力與隱藏特質線索"],people:["♡","手機與人際","查看聯絡人和關係進度"],log:["≡","星途紀錄","回顧每週成果與重大選擇"],map:["⌖","星望市地圖","選擇自由活動要前往的地點"],jobs:["▤","通告中心","接取邀約、參加試鏡與管理合約"],npc:["◈","人物檔案","已認識人物的資料與關係"],agency:["◆","經紀公司","查看公司資料、投遞、面談與簽約進度"]}[state.appOpen];const views={planner:plannerApp,stats:statsApp,people:peopleApp,log:logApp,map:mapApp,jobs:jobsApp,npc:npcApp,agency:agencyApp};const body=views[state.appOpen]();return `<div class="app-backdrop" data-close-app></div><section class="app-window ${state.appOpen}"><header class="window-bar"><div class="window-icon">${meta[0]}</div><div><h2>${meta[1]}</h2><p>${meta[2]}</p></div>${state.appOpen==="planner"?`<button class="window-start" id="begin-week">開始這週 →</button>`:""}<button class="window-close" data-close-app aria-label="關閉">×</button></header><div class="window-body">${body}</div></section>`}

function budget(){return state.schedule.reduce((s,id)=>s+ACTIONS[id].cost,0)}
function forecastFatigue(){return state.schedule.reduce((s,id)=>Math.max(0,s+ACTIONS[id].fatigue),state.fatigue)}
function plannerApp(){const spend=budget(),fat=forecastFatigue(),train=state.schedule.filter(id=>ACTIONS[id].type==="train").length,work=state.schedule.filter(id=>["work","job"].includes(ACTIONS[id].type)).length;return `<div class="planner-app">${state.jobStage==="active"?`<button class="contract-alert" data-open-app="jobs"><span>進行中通告</span><b>晨露汽水形象廣告</b><strong>剩餘 ${state.jobRemaining} 次・第 ${state.jobDeadline} 週截止</strong><small>指定執行日：每週${jobWorkDaysText()}</small><em>查看合約 →</em></button>`:""}<div class="week-brief"><div><span>本週任務</span><b>準備簽約面談</b><small>訓練 2 天＋工作 1 次＋週末疲勞 ≤ 60</small></div><strong>獎勵<br><b>$1,500・簽約＋10%</b></strong></div><div class="focus-row"><span>本週策略</span>${Object.entries(FOCUSES).map(([id,f])=>`<button class="${state.focus===id?"active":""}" data-focus="${id}" title="${f.note}">${f.icon} ${f.label}</button>`).join("")}</div><div class="calendar-head"><div><b>八月・第 ${state.week} 週</b><small>點一天打開行程選單</small></div><div><button id="copy" ${state.lastSchedule?"":"disabled"}>複製上週</button><button id="rest-all">全部休息</button></div></div><div class="ipad-calendar">${state.schedule.map((id,i)=>calendarDay(id,i)).join("")}</div><div class="week-check"><span>訓練 <b>${train}/2</b></span><span>工作 <b>${work}/1</b></span><span>預估疲勞 <b class="${fat>60?"bad":""}">${fat}</b></span><span>本週支出 <b class="${spend>state.money?"bad":""}">${money(spend)}</b></span><em>${spend>state.money?"預算不足，請調整行程":fat>60?"任務可能因疲勞過高而失敗":"本週任務條件可達成"}</em></div>${state.notice?`<div class="mini-toast">✓ ${esc(state.notice)}</div>`:""}${state.drawerOpen?activityDrawer():""}</div>`}
function calendarDay(id,i){const a=ACTIONS[id],freePlace=id==="free"&&state.mapLocation?MAP_LOCATIONS[state.mapLocation].name:null,interviewLabel=id==="agency_interview"&&state.agencyInterview?`${AGENCIES[state.agencyInterview.agencyId].shortName}面談`:null,dueDay=state.jobStage==="active"&&JOB.workDays.includes(i);return `<button class="calendar-cell ${state.selectedDay===i?"selected":""} ${dueDay?"due-day":""} ${id==="agency_interview"?"important-day":""}" data-day="${i}" ${dueDay?`title="通告指定工作日"`:id==="agency_interview"?`title="重要行程・經紀公司面談"`:""}><span>${i+1}<small>週${SHORT[i]}</small></span><i class="${a.type}">${a.icon}</i><b>${interviewLabel||freePlace||a.short}</b><em>${id==="agency_interview"?"不收費・重要行程":a.cost?money(a.cost):"免費"}${id==="adshoot"&&state.jobStage==="active"?`・剩 ${state.jobRemaining} 次`:""}</em></button>`}
function activityDrawer(){const entries=Object.entries(ACTIONS).filter(([id,a])=>id!=="agency_interview"&&(id!=="adshoot"||state.jobStage==="active")&&(state.filter==="全部"||a.group===state.filter));return `<div class="drawer-shade" data-close-drawer></div><aside class="activity-drawer"><header><div><span>正在安排</span><b>${DAYS[state.selectedDay]}</b></div><button data-close-drawer>×</button></header><nav>${["全部","訓練","工作","生活","休息"].map(f=>`<button class="${state.filter===f?"active":""}" data-filter="${f}">${f}</button>`).join("")}</nav><div class="drawer-list">${entries.map(([id,a])=>{const unavailable=id==="adshoot"&&!JOB.workDays.includes(state.selectedDay);return `<button class="${state.schedule[state.selectedDay]===id?"active":""} ${unavailable?"unavailable":""}" data-pick="${id}" ${unavailable?"disabled":""}><i class="${a.type}">${a.icon}</i><span><b>${a.label}</b><small>${unavailable?`此通告僅能排在每週${jobWorkDaysText()}`:a.note}</small></span><em>${a.cost?money(a.cost):"免費"}<small>疲勞 ${a.fatigue>0?"+":""}${a.fatigue}</small></em></button>`}).join("")}</div></aside>`}

function statsApp(){const best=Object.entries(state.stats).sort((a,b)=>b[1]-a[1]).slice(0,3);return `<div class="inside-page"><div class="inside-title"><div><span>ABILITIES</span><h2>能力資料</h2></div><p>目前最高：${best.map(([n,v])=>`${n} ${v}`).join("・")}</p></div><div class="stats-columns">${Object.entries(ABILITY_GROUPS).map(([g,names])=>`<section><h3>${g}</h3>${names.map(n=>`<div class="stat-row"><span>${n}</span><i><b style="width:${width(state.stats[n])}%"></b></i><strong>${state.stats[n]}<small>/1000</small></strong></div>`).join("")}</section>`).join("")}</div><div class="hidden-traits"><h3>隱藏特質</h3><p>實際數值不公開，會透過通告、活動、事件選項與 NPC 反應逐漸顯露。</p><div class="hidden-grid">${[...HIDDEN_TRAITS,"運氣"].map(n=>`<span>${n}<b>尚待觀察</b></span>`).join("")}</div></div><div class="rep-section"><h3>娛樂圈評價</h3><div class="hidden-grid">${Object.entries(state.rep).map(([n,v])=>`<span>${n}<b>${v}</b></span>`).join("")}</div></div></div>`}
function peopleApp(){return `<div class="inside-page"><div class="inside-title"><div><span>CONTACTS</span><h2>手機通訊錄</h2></div><p>${state.knownPeople.length} 位聯絡人</p></div>${state.knownPeople.length?`<div class="contact-list">${state.knownPeople.map(id=>{const n=NPCS[id];return `<article><div>${n.avatar}</div><span><b>${n.name}</b><small>${n.job}</small></span><em>剛認識</em></article>`}).join("")}</div>`:`<div class="tablet-empty"><span>♡</span><h3>還沒有認識任何人</h3><p>第一輪沒有免費人脈。安排自由活動或參加工作，讓第一次相遇真的發生。</p><button data-go-free>去安排自由活動</button></div>`}</div>`}
function logApp(){return `<div class="inside-page"><div class="inside-title"><div><span>CAREER LOG</span><h2>星途紀錄</h2></div><p>已完成 ${state.history.length} 週</p></div>${state.flags.length?`<div class="inside-title"><div><span>BUTTERFLY FLAGS</span><h3>重要旗標</h3></div><p>${state.flags.length} 項</p></div><div class="log-list">${[...state.flags].reverse().map(f=>`<article><b>第 ${f.week} 週</b><span>旗標</span><small>${esc(f.label)}｜${esc(f.note)}</small></article>`).join("")}</div>`:""}${state.history.length?`<div class="inside-title"><div><span>WEEKLY LOG</span><h3>每週紀錄</h3></div></div><div class="log-list">${[...state.history].reverse().map(w=>`<article><b>第 ${w.week} 週</b><span>${w.hospitalized?"住院":w.results.filter(r=>r.success).length+" 次成功"}</span><small>${w.results.map(r=>r.action).join("・")||"住院休養"}</small></article>`).join("")}</div>`:`<div class="tablet-empty"><span>✦</span><h3>第一頁還是空白</h3><p>完成第一週後，每日成果與重大選擇會整理在這裡。</p></div>`}</div>`}

const MAP_LOCATIONS={radio:{name:"星望廣播電臺",area:"傳媒區",icon:"聲",note:"節目錄音、主持與業界人士出入的地方。",effect:"可能認識主持人，提升口才或社交"},livehouse:{name:"月蝕 Live House",area:"舊城區",icon:"樂",note:"新人樂團與地下歌手聚集的小型展演空間。",effect:"獲得舞台經驗、歌藝或創作靈感"},park:{name:"星光河濱公園",area:"河岸區",icon:"休",note:"適合散步、慢跑與放空的公共空間。",effect:"降低疲勞並可能觸發日常事件"},studio:{name:"十七號攝影棚",area:"影視園區",icon:"影",note:"廣告與戲劇經常在此拍攝，目前尚未開放。",effect:"需要通告或業界關係才能進入",locked:true}};
function mapApp(){return `<div class="map-page"><div class="map-intro"><div><span>STARWISH CITY</span><h2>今天想去哪裡？</h2><p>${state.selectedDay!=null?`將為${DAYS[state.selectedDay]}安排自由活動。`:"選擇地點探索星望市。"}</p></div><b>交通費 $300</b></div><div class="city-map">${Object.entries(MAP_LOCATIONS).map(([id,l])=>`<button class="map-place ${l.locked?"locked":""} ${state.mapLocation===id?"selected":""}" ${l.locked?"disabled":""} data-map-location="${id}"><i>${l.icon}</i><span><small>${l.area}</small><b>${l.name}</b><em>${l.note}</em><strong>${l.effect}</strong></span>${l.locked?`<u>尚未解鎖</u>`:`<u>選擇地點 →</u>`}</button>`).join("")}</div><aside class="map-tip">自由活動必須先選擇地點；地點會影響可能遇見的人物、能力成長與事件。</aside></div>`}

function jobsApp(){const stage=state.jobStage,showRequirements=["available","applied","audition","failed"].includes(stage);return `<div class="jobs-page"><div class="job-board-head"><div><span>CASTING BOARD / 001</span><h2>${JOB.title}</h2><p>${JOB.tagline}</p></div><strong class="job-status">${stage==="available"?"可接取":stage==="applied"?"等待試鏡":stage==="audition"?"試鏡進行中":stage==="failed"?"未獲選":stage==="active"?"合約執行中":stage==="completed"?"已完成":stage==="breached"?"已違約":"試鏡通過"}</strong></div>${showRequirements?jobQualificationPanel():""}${state.jobNotice?`<div class="job-notice">${esc(state.jobNotice)}</div>`:""}${jobStageView(stage)}</div>`}
function jobWorkDaysText(){return JOB.workDays.map(i=>"週"+SHORT[i]).join("、")}
function jobRequirementsHtml(){return JOB.requirements.map(([n,min])=>{const current=state.stats[n]||0,met=current>=min;return `<span class="${met?"met":"unmet"}"><b>${n}</b><small>目前 ${current}／需求 ${min}</small><em>${met?"符合":"未達"}</em></span>`}).join("")}
function jobQualificationPanel(){const met=JOB.requirements.filter(([n,min])=>(state.stats[n]||0)>=min).length;return `<section class="qualification-panel"><div><span>試鏡資質需求</span><h3>${met===JOB.requirements.length?"已符合全部門檻":met?`符合 ${met}／${JOB.requirements.length} 項，可嘗試挑戰`:"目前資質仍有差距"}</h3><p>資質會影響獲選機率，但不保證結果。</p></div><div class="req-list">${jobRequirementsHtml()}</div></section>`}
function resolveJobAudition(choice){const delta=JOB.requirements.reduce((sum,[n,min])=>sum+((state.stats[n]||0)-min),0)/JOB.requirements.length;const hiddenBonus=choice==="bold"?((state.hidden.膽識||500)-500)/18:0;const chance=Math.max(8,Math.min(92,55+delta*.75+(choice==="natural"?10:-5)+hiddenBonus));const passed=Math.random()*100<chance;state.stats.鏡頭感=Math.min(1000,state.stats.鏡頭感+(passed?4:2));state.jobStage=passed?"passed":"failed";state.jobNotice=passed?`試鏡獲選！這次的現場表現屬於「${successRateLabel(chance)}」。`:`這次沒有獲選，現場評估屬於「${successRateLabel(chance)}」；仍獲得鏡頭感＋2。`}
function jobStageView(stage){if(stage==="available")return `<div class="job-layout"><section class="job-sheet"><h3>通告資料</h3><dl><div><dt>委託品牌</dt><dd>${JOB.brand}</dd></div><div><dt>報酬</dt><dd>${money(JOB.pay)}</dd></div><div><dt>工作次數</dt><dd>${JOB.sessions} 次拍攝</dd></div><div><dt>指定工作日</dt><dd>每週${jobWorkDaysText()}</dd></div><div><dt>完成期限</dt><dd>第 ${state.jobDeadline} 週週日</dd></div></dl></section><section class="job-action"><span>目前評估</span><h3>值得一試</h3><p>品牌正在尋找自然、有朝氣的新人。資質會影響試鏡結果，通過後才會建立正式合約。</p><button data-job-action="apply">接取試鏡邀請 →</button></section></div>`;if(stage==="applied")return `<div class="audition-lobby"><span>AUDITION READY</span><h2>試鏡通知已確認</h2><p>上方已列出目前資質與需求門檻。試鏡不占用本週行程，但結果會依能力與現場選擇判定。</p><div><b>地點</b>十七號攝影棚・B 棚</div><div><b>提示</b>品牌喜歡自然的笑容，不需要用力過猛。</div><button data-job-action="start-audition">進入試鏡現場 →</button></div>`;if(stage==="audition")return `<div class="audition-room"><div><span>CAMERA TEST</span><h2>導演請你對鏡頭喝下一口汽水</h2><p>「不用照腳本，給我一個最像妳自己的反應。」</p></div><section><button data-audition-choice="natural"><b>自然笑著說：「好喝耶。」</b><small>親和力與鏡頭感判定・較穩定</small></button><button data-audition-choice="bold"><b>即興演出被氣泡嗆到的反應</b><small>資質與膽識判定・高風險</small></button></section></div>`;if(stage==="failed")return `<div class="contract-result breached"><span>AUDITION COMPLETE</span><h2>這次沒有獲選</h2><p>資質與現場表現都會影響結果。可以先訓練再重新投遞，不會憑一顆按鈕保送。</p><button data-job-action="retry">重新確認試鏡資料 →</button></div>`;if(stage==="passed")return `<div class="contract-result"><span>✓ AUDITION PASSED</span><h2>試鏡通過！</h2><p>導演記住了妳的鏡頭反應。簽約後必須在第 ${state.jobDeadline} 週以前完成 ${JOB.sessions} 次拍攝，而且只能安排在每週${jobWorkDaysText()}。</p><button data-job-action="sign">簽署通告合約 →</button></div>`;if(stage==="active")return `<div class="contract-dashboard"><section><span>ACTIVE CONTRACT</span><h2>${JOB.title}</h2><p>請把「廣告拍攝」排入指定工作日，每完成一天會扣除一次剩餘工作。</p><div class="contract-progress"><i><b style="width:${(JOB.sessions-state.jobRemaining)/JOB.sessions*100}%"></b></i><strong>已完成 ${JOB.sessions-state.jobRemaining}／${JOB.sessions} 次</strong></div></section><aside><b>剩餘 ${state.jobRemaining} 次</b><span>可執行日：每週${jobWorkDaysText()}</span><span>第 ${state.jobDeadline} 週週日截止</span><button data-job-action="schedule">排入指定工作日 →</button></aside></div>`;if(stage==="breached")return `<div class="contract-result breached"><span>! CONTRACT BREACHED</span><h2>通告逾期</h2><p>期限內仍有 ${state.jobRemaining} 次拍攝未完成，品牌已終止合約。正式版將在此結算違約金、業界評價與後續事件。</p><button data-open-app="planner">回到行程表 →</button></div>`;return `<div class="contract-result"><span>★ CONTRACT COMPLETE</span><h2>通告完成！</h2><p>品牌已支付 ${money(JOB.pay)}，作品將成為妳的第一份正式履歷。</p><button data-open-app="planner">回到行程表 →</button></div>`}

function npcApp(){const ids=state.knownPeople;if(!ids.length)return `<div class="tablet-empty"><span>◈</span><h3>還沒有認識任何人</h3><p>第一輪沒有免費人脈。安排自由活動或參加工作，讓第一次相遇真的發生，對方才會出現在這裡。</p><button data-go-free>去安排自由活動</button></div>`;const current=ids.includes(state.selectedNpc)?state.selectedNpc:ids[0],npc=NPCS[current],rel=state.relationships[current]||{closeness:0,trust:0,romance:"none"},familiar=state.familiarNpcs.includes(current);return `<div class="npc-dossier"><nav class="npc-list">${ids.map(id=>{const n=NPCS[id];return `<button class="${id===current?"active":""}" data-select-npc="${id}"><i>${n.avatar}</i><span><b>${n.name}</b><small>${n.job}</small></span></button>`}).join("")}</nav><section class="npc-card"><div class="npc-card-head"><div class="npc-photo">${npc.avatar}</div><div><span>已認識${familiar?"・似曾相識":""}</span><h2>${npc.name}</h2><p>${npc.bio}</p></div></div><dl><div><dt>職業</dt><dd>${npc.job}</dd></div><div><dt>常出沒地點</dt><dd>${npc.location}</dd></div><div><dt>好感</dt><dd>${rel.closeness}／100</dd></div><div><dt>信任</dt><dd>${rel.trust}／100</dd></div><div><dt>戀愛狀態</dt><dd>${rel.romance==="none"?"尚未發展":rel.romance}</dd></div><div><dt>互動方式</dt><dd>透過行程、事件與合作推進</dd></div></dl><div class="npc-card-actions"><button class="main-btn" disabled>傳送訊息（後續開放）</button><button class="main-btn" disabled>安排拜訪（後續開放）</button></div></section></div>`}

// ---- 經紀公司：資格判定（純函式，不碰畫面） ----
function agencyRequirementRows(agency){const rows=[{label:"簽約準備度",current:state.contract,required:agency.requirements.contractReadiness,unit:"%"}];agency.requirements.abilities.forEach(([n,min])=>rows.push({label:n,current:state.stats[n]||0,required:min,unit:""}));return rows}
function checkAgencyEligibility(agency){const missing=agencyRequirementRows(agency).filter(r=>r.current<r.required);return{met:missing.length===0,missing}}
function canApplyToAgency(agency){if(state.currentAgencyId)return false;const app=state.agencyApplications[agency.id];if(app&&app.status!=="rejected")return false;return checkAgencyEligibility(agency).met}
// ---- 經紀公司：狀態處理（唯一改變 state 的地方） ----
function applyToAgency(id){const agency=AGENCIES[id];if(!canApplyToAgency(agency))return;state.agencyApplications[id]={status:"applied",appliedWeek:state.week};state.notice=`已向${agency.name}投遞新人資料。`}
function releaseAgencyInterview(){if(!state.agencyInterview)return;const app=state.agencyApplications[state.agencyInterview.agencyId];if(app&&app.status==="interview_scheduled")app.status="applied";state.agencyInterview=null}
function scheduleAgencyInterview(id){const agency=AGENCIES[id],app=state.agencyApplications[id];if(!app||app.status!=="applied")return;if(state.agencyInterview&&state.agencyInterview.agencyId!==id){state.notice="本週已排入其他面談，請先完成後再安排。";return}const dayIndex=state.schedule.findIndex(a=>a==="rest"||a==="free");if(dayIndex<0){state.notice="本週沒有空檔，請先移除一項行程。";return}state.schedule[dayIndex]="agency_interview";state.agencyInterview={agencyId:id,dayIndex};app.status="interview_scheduled";state.notice=`${agency.name}面談已排入${DAYS[dayIndex]}。`}
function agencyInterviewChance(agency,choice){const reqAvg=agency.requirements.abilities.reduce((s,[n,min])=>s+((state.stats[n]||0)-min),0)/agency.requirements.abilities.length;const readinessGap=state.contract-agency.requirements.contractReadiness;const publicPair=choice==="steady"?["口才","親和力"]:["鏡頭感","肢體表現"];const publicAvg=publicPair.reduce((s,n)=>s+(state.stats[n]||0),0)/publicPair.length;const hiddenPair=choice==="steady"?["自律"]:["膽識","野心"];const hiddenAvg=hiddenPair.reduce((s,n)=>s+((state.hidden[n]||500)-500),0)/hiddenPair.length;const fatiguePenalty=state.fatigue>60?(state.fatigue-60)*.3:0;const moodBonus=(state.mood-70)*.15;const variance=choice==="bold"?random(-14,14):random(-7,7);const base=50+reqAvg*.3+readinessGap*.4+(publicAvg-75)*.18+hiddenAvg*.05+moodBonus-fatiguePenalty+variance;return Math.max(5,Math.min(95,Math.round(base)))}
function acceptAgencyOffer(){if(!state.agencyOffer)return;const id=state.agencyOffer.agencyId,agency=AGENCIES[id];state.currentAgencyId=id;state.agencySignedWeek=state.week;state.agencyContractEndWeek=state.week+agency.contract.durationWeeks-1;state.agencyStatus="signed";state.agencyApplications[id].status="signed";state.agencyOffer=null;state.flags.push({week:state.week,label:`正式簽約：${agency.name}`,note:`成為${agency.name}旗下新人，合約至第 ${state.agencyContractEndWeek} 週。`});state.notice=`已正式簽約${agency.name}！`}
function declineAgencyOffer(){if(!state.agencyOffer)return;const id=state.agencyOffer.agencyId,agency=AGENCIES[id];state.agencyApplications[id].status="declined";state.agencyOffer=null;state.notice=`已婉拒${agency.name}的合約。`}
// ---- 經紀公司：通告收入計算（可重複使用，供任何正式通告呼叫） ----
function calculateJobIncome(grossPay){const rate=state.currentAgencyId?AGENCIES[state.currentAgencyId].contract.commissionRate:0;const commission=Math.round(grossPay*rate);return{gross:grossPay,commission,net:grossPay-commission}}
// ---- 經紀公司：畫面 ----
function agencyOverallStatusText(){if(state.currentAgencyId){const agency=AGENCIES[state.currentAgencyId],remain=Math.max(0,state.agencyContractEndWeek-state.week+1);return `${agency.name}旗下新人・合約剩餘 ${remain} 週`}if(state.agencyOffer)return `收到 ${AGENCIES[state.agencyOffer.agencyId].name} 的合約，尚未決定`;const eligible=AGENCY_LIST.filter(a=>checkAgencyEligibility(a).met).length;return `未簽約新人・目前可投遞 ${eligible}／${AGENCY_LIST.length} 間公司`}
function agencyStatusLabel(agency){if(state.currentAgencyId===agency.id)return"已正式簽約";if(state.agencyOffer&&state.agencyOffer.agencyId===agency.id)return"收到合約";const app=state.agencyApplications[agency.id];if(!app)return checkAgencyEligibility(agency).met?"尚未投遞":"尚未符合投遞資格";if(app.status==="applied")return"已投遞，等待安排面談";if(app.status==="interview_scheduled")return `面談已排入${DAYS[state.agencyInterview.dayIndex]}`;if(app.status==="rejected")return"未獲錄取";if(app.status==="declined")return"已拒絕合約";return"查看中"}
function agencyIneligibleBlock(eligibility){return `<p>目前尚未符合投遞資格，還缺：</p><ul class="agency-missing">${eligibility.missing.map(m=>`<li>${esc(m.label)}（目前 ${m.current}${m.unit}／需求 ${m.required}${m.unit}）</li>`).join("")}</ul><button class="main-btn" disabled>目前尚未符合投遞資格</button>`}
function agencyContractCard(agency){return `<section class="agency-action agency-contract-card"><span>OFFICIAL CONTRACT</span><h3>${esc(agency.name)}正式合約</h3><dl><div><dt>合約期間</dt><dd>${agency.contract.durationWeeks} 週（約 ${Math.round(agency.contract.durationWeeks/52*10)/10} 年）</dd></div><div><dt>起始週</dt><dd>第 ${state.week} 週</dd></div><div><dt>到期週</dt><dd>第 ${state.week+agency.contract.durationWeeks-1} 週</dd></div><div><dt>經紀抽成</dt><dd>${Math.round(agency.contract.commissionRate*100)}%</dd></div><div><dt>合約定位</dt><dd>${esc(agency.contract.description)}</dd></div><div><dt>公司擅長領域</dt><dd>${agency.specialties.map(esc).join("、")}</dd></div><div><dt>簽約後身分</dt><dd>${esc(agency.shortName)}・旗下新人</dd></div></dl><p>請詳閱條款；一旦簽約，將無法再投遞其他經紀公司。</p><div class="agency-contract-actions"><button class="main-btn" data-agency-action="accept-offer">接受合約</button><button class="ghost-btn" data-agency-action="decline-offer">婉拒合約</button></div></section>`}
function agencySignedDashboard(agency){const remain=Math.max(0,state.agencyContractEndWeek-state.week+1);return `<section class="agency-action agency-signed"><span>目前公司狀態</span><h3>${esc(agency.name)}・旗下新人</h3><div class="agency-signed-grid"><div><small>合約起始週</small><b>第 ${state.agencySignedWeek} 週</b></div><div><small>合約到期週</small><b>第 ${state.agencyContractEndWeek} 週</b></div><div><small>剩餘週數</small><b>${remain} 週</b></div><div><small>經紀抽成</small><b>${Math.round(agency.contract.commissionRate*100)}%</b></div></div><p>擅長領域：${agency.specialties.map(esc).join("、")}</p><div class="agency-upcoming"><span>後續開放</span>${["聯絡經紀人","公司內部通告","公司培訓"].map(t=>`<em>${t}・後續開放</em>`).join("")}</div></section>`}
function agencyActionPanel(agency,eligibility,app){if(state.currentAgencyId&&state.currentAgencyId!==agency.id)return `<section class="agency-action"><span>目前申請狀態</span><h3>已與其他公司簽約</h3><p>你已是${esc(AGENCIES[state.currentAgencyId].name)}的旗下新人，暫時無法投遞其他經紀公司。</p></section>`;if(app&&app.status==="declined")return `<section class="agency-action"><span>目前申請狀態</span><h3>已拒絕合約</h3><p>你先前婉拒了${esc(agency.name)}的合約，暫時不會再收到相同邀約。可以持續累積能力與作品，等待日後的機會。</p></section>`;if(app&&app.status==="interview_scheduled")return `<section class="agency-action"><span>目前申請狀態</span><h3>面談已排入${DAYS[state.agencyInterview.dayIndex]}</h3><p>開始這一週後，面談當天會出現在逐日行程中，屆時可以選擇如何應對這場面談。</p></section>`;if(app&&app.status==="applied")return `<section class="agency-action"><span>目前申請狀態</span><h3>已投遞，等待安排面談</h3><p>公司已收到新人資料。投遞本身不會占用行程，接下來請把面談排入本週行程。</p><button class="main-btn" data-agency-action="schedule-interview">排入本週行程 →</button></section>`;if(app&&app.status==="rejected")return `<section class="agency-action"><span>目前申請狀態</span><h3>未獲錄取</h3><p>這次面談沒有成功，但仍是寶貴的實戰經驗。可以持續訓練，符合條件後再重新投遞。</p>${eligibility.met?`<button class="main-btn" data-agency-action="apply">重新投遞新人資料 →</button>`:agencyIneligibleBlock(eligibility)}</section>`;if(eligibility.met)return `<section class="agency-action"><span>目前申請狀態</span><h3>尚未投遞</h3><p>你已符合${esc(agency.name)}的簽約需求，可以投遞新人資料。</p><button class="main-btn" data-agency-action="apply">投遞新人資料 →</button></section>`;return `<section class="agency-action"><span>目前申請狀態</span><h3>尚未符合投遞資格</h3>${agencyIneligibleBlock(eligibility)}</section>`}
function agencyDetailView(agency){const rows=agencyRequirementRows(agency),eligibility=checkAgencyEligibility(agency),isSigned=state.currentAgencyId===agency.id,offerHere=state.agencyOffer&&state.agencyOffer.agencyId===agency.id,app=state.agencyApplications[agency.id];return `<header class="agency-detail-head"><div><span>${esc(agency.type)}・${esc(agency.scale)}</span><h2>${esc(agency.name)}</h2><p>${esc(agency.description)}</p></div><div class="agency-tags">${agency.specialties.map(s=>`<em>${esc(s)}</em>`).join("")}</div></header><section class="agency-requirements"><h3>簽約需求</h3><div class="req-list">${rows.map(r=>`<span class="${r.current>=r.required?"met":"unmet"}"><b>${esc(r.label)}</b><small>目前 ${r.current}${r.unit}／需求 ${r.required}${r.unit}</small><em>${r.current>=r.required?"符合":"未達"}</em></span>`).join("")}</div></section><section class="agency-contract-terms"><h3>合約條件</h3><dl><div><dt>合約期間</dt><dd>${agency.contract.durationWeeks} 週（約 ${Math.round(agency.contract.durationWeeks/52*10)/10} 年）</dd></div><div><dt>經紀抽成</dt><dd>${Math.round(agency.contract.commissionRate*100)}%</dd></div><div><dt>合約定位</dt><dd>${esc(agency.contract.description)}</dd></div></dl></section>${isSigned?agencySignedDashboard(agency):offerHere?agencyContractCard(agency):agencyActionPanel(agency,eligibility,app)}`}
function agencyApp(){const selectedId=state.selectedAgencyId||AGENCY_LIST[0].id,agency=AGENCIES[selectedId]||AGENCY_LIST[0];return `<div class="agency-page"><div class="agency-status-bar"><span>目前狀態</span><b>${agencyOverallStatusText()}</b></div><div class="agency-layout"><nav class="agency-list">${AGENCY_LIST.map(a=>`<button class="${a.id===agency.id?"active":""}" data-select-agency="${a.id}"><b>${esc(a.name)}</b><small>${esc(a.type)}</small><em>${agencyStatusLabel(a)}</em></button>`).join("")}</nav><section class="agency-detail">${agencyDetailView(agency)}</section></div></div>`}

function decisionFor(id){if(id==="agency_interview"&&state.agencyInterview){const agency=AGENCIES[state.agencyInterview.agencyId];return{title:`${agency.name}面談`,text:"人資窗口準備好聽你聊聊自己，你打算怎麼呈現這次機會？",choices:[{id:"steady",label:"穩健回答：說明訓練與職涯規劃",note:`偏向口才、親和力與自律・${successRateLabel(agencyInterviewChance(agency,"steady"))}`},{id:"bold",label:"展現企圖心：談論想爭取的舞台",note:`偏向膽識、野心與鏡頭感・${successRateLabel(agencyInterviewChance(agency,"bold"))}`}]}}if(id==="free"&&state.mapLocation){const l=MAP_LOCATIONS[state.mapLocation];return{title:`抵達${l.name}`,text:l.note,choices:[{id:"explore",label:"四處走走，主動探索",note:"提高遇見人物或事件的機會"},{id:"focus",label:"專注體驗這個地點",note:"較容易獲得能力或狀態成長"}]}}if(id==="audition")return{title:"導演臨時更換了台詞",text:"輪到你試鏡前，現場突然要求即興。你打算怎麼應對？",choices:[{id:"safe",label:"照原本準備穩穩演",note:"成功率較高，成果穩定"},{id:"bold",label:"順勢加入自己的設計",note:"風險較高，大成功時曝光更多"}]};if(id==="free")return{title:"午後還沒有安排",text:"星望市今天很熱鬧，你想把空閒時間花在哪裡？",choices:[{id:"radio",label:"去廣播電臺附近逛逛",note:"可能遇見業界人物"},{id:"livehouse",label:"鑽進巷子裡的 Live House",note:"可能獲得靈感與舞台經驗"}]};if(id==="street")return{title:"街頭的人比預期更多",text:"你選好位置，卻發現路人來去匆匆。要怎麼抓住注意力？",choices:[{id:"steady",label:"唱最熟悉的歌",note:"穩定演出，成功率較高"},{id:"interact",label:"主動邀請路人點歌",note:"考驗社交，收益波動更大"}]};return null}
function runnerView(){const i=state.runnerDay,a=ACTIONS[state.schedule[i]];return `<main class="event-screen"><img src="./assets/star-city-street.webp" alt="星望市娛樂街景"><div class="event-top"><div class="logo dark">✦ 星途未定</div><div>${state.week} 週・DAY ${i+1}　${DAYS[i]}</div><div>體力 ${state.stamina}　疲勞 ${state.fatigue}</div></div><div class="day-track">${DAYS.map((d,x)=>`<i class="${x<i?"done":x===i?"now":""}">${x<i?"✓":x+1}<small>${SHORT[x]}</small></i>`).join("")}</div><section class="story-box"><div class="story-action"><i>${a.icon}</i><span><small>今日行程</small><b>${a.label}</b><em>${a.note}</em></span></div>${state.runnerPhase==="loading"?`<div class="story-loading"><i></i><b>今天正在發生……</b></div>`:state.runnerPhase==="decision"?decisionView():resultView()} </section></main>`}
function decisionView(){const d=state.runnerDecision;return `<div class="decision"><span>CHOICE</span><h2>${d.title}</h2><p>${d.text}</p><div>${d.choices.map(c=>`<button data-choice="${c.id}"><b>${c.label}</b><small>${c.note}</small></button>`).join("")}</div></div>`}
function resultView(){const r=state.runnerResult;return `<div class="day-result ${r.success?"success":"fail"}"><span>${r.success?"RESULT・SUCCESS":"RESULT・EXPERIENCE"}</span><h2>${r.title}</h2><p>${r.text}</p><div><b>💰 ${money(state.money)}</b><b>★ 知名度 ${state.fame}</b><b>♡ 粉絲 ${state.fans}</b></div><button class="main-btn" id="next-day">${state.runnerDay===6?"查看本週總結":"前往"+DAYS[state.runnerDay+1]} →</button></div>`}

function applyGains(gains){const out=[];gains.forEach(([n,min,max])=>{let gain=random(min,max)+(state.focus==="growth"?1:0);state.stats[n]=Math.min(1000,state.stats[n]+gain);out.push(`<b>${n}＋${gain}</b>`)});return out.join("、")}
function startDay(){state.runnerResult=null;state.runnerDecision=null;state.runnerPhase="loading";render();setTimeout(()=>{const d=decisionFor(state.schedule[state.runnerDay]);if(d){state.runnerDecision=d;state.runnerPhase="decision";render()}else resolveDay(null)},650)}
function resolveDay(choice){const id=state.schedule[state.runnerDay],a=ACTIONS[id];let title="成功！",text="",success=true;state.money-=a.cost;
 if(a.type==="train"){text=`課程順利結束，${applyGains(a.gains)}。學費 <b>－${money(a.cost)}</b>。`;state.stamina=Math.max(0,state.stamina-a.stamina);state.fatigue+=a.fatigue}
 else if(id==="rest"){title="好好休息！";const reduced=Math.min(state.fatigue,18);state.fatigue-=reduced;state.stamina=Math.min(100,state.stamina+24);state.mood=Math.min(100,state.mood+3);text=`體力 <b>＋24</b>、疲勞 <b>－${reduced}</b>。專業躺平也是職涯管理。`}
 else if(id==="free"){state.fatigue+=3;state.stamina=Math.max(0,state.stamina-4);const loc=state.mapLocation||"park";if(loc==="radio"&&choice==="explore"&&!state.knownPeople.includes("jiqing")){const familiar=state.familiarNpcs.includes("jiqing");state.knownPeople.push("jiqing");state.selectedNpc="jiqing";state.relationships.jiqing={closeness:familiar?18:8,trust:familiar?22:12,romance:"none"};state.contract+=4;text=familiar?"你一靠近就覺得眼熟——原來是<b>紀晴</b>，她似乎也對你有點印象，很快就聊開了。簽約進度 <b>＋4%</b>。":"你幫忙撿回散落的訪綱，第一次認識主持人<b>紀晴</b>。簽約進度 <b>＋4%</b>。";state.flags.push({week:state.week,label:"第一次認識紀晴",note:familiar?"雖是新的一輪，卻對彼此有眼熟印象，很快破冰。":"撿回散落的訪綱，建立初次印象。"})}else if(loc==="livehouse"){const g=random(3,7);state.stats.靈感+=g;state.stats.歌藝+=2;text=`你看了一場新人演出，<b>靈感＋${g}、歌藝＋2</b>。`}else if(loc==="park"){const reduced=Math.min(state.fatigue,8);state.fatigue-=reduced;state.mood=Math.min(100,state.mood+5);text=`河邊散步讓妳喘了口氣，<b>疲勞－${reduced}、心情＋5</b>。`}else{const g=random(2,5);state.stats.口才+=g;text=`你在電臺旁觀摩錄影，<b>口才＋${g}</b>。`}}
 else if(id==="adshoot"){if(state.jobStage!=="active"){title="通告已不在執行中";success=false;text="這份行程不再有效，今天不會重複計算報酬或完成次數。"}else if(!JOB.workDays.includes(state.runnerDay)){title="今天無法執行通告";success=false;text=`合約指定工作日為每週${jobWorkDaysText()}，今天不能計入完成次數。`}else{state.fatigue+=a.fatigue;state.stamina=Math.max(0,state.stamina-a.stamina);state.jobRemaining=Math.max(0,state.jobRemaining-1);const g=random(3,6);state.stats.鏡頭感=Math.min(1000,state.stats.鏡頭感+g);if(state.jobRemaining===0){state.jobStage="completed";state.schedule=state.schedule.map((scheduled,idx)=>idx>state.runnerDay&&scheduled==="adshoot"?"rest":scheduled);const income=calculateJobIncome(JOB.pay);state.money+=income.net;state.fame+=18;state.fans+=120;text=`完成最後一次拍攝！<b>鏡頭感＋${g}</b>。通告總額 <b>${money(income.gross)}</b>，公司抽成 <b>－${money(income.commission)}</b>，實領 <b>＋${money(income.net)}</b>、知名度＋18、粉絲＋120。`}else{text=`完成一階段拍攝，<b>鏡頭感＋${g}</b>。合約還剩 <b>${state.jobRemaining} 次</b>工作。`}}}
 else if(id==="agency_interview"){const active=state.agencyInterview,activeApp=active&&state.agencyApplications[active.agencyId];const valid=active&&active.dayIndex===state.runnerDay&&activeApp&&activeApp.status==="interview_scheduled";if(!valid){title="面談已取消或失效";success=false;text="這場面談目前已不存在，今天不會產生任何結果，也不會重複計算。"}else{const agency=AGENCIES[active.agencyId];state.fatigue+=a.fatigue;state.stamina=Math.max(0,state.stamina-a.stamina);const chance=agencyInterviewChance(agency,choice);success=random(1,100)<=chance;const bumpStat=choice==="steady"?"口才":"鏡頭感";if(success){const gain=random(4,8);state.stats[bumpStat]=Math.min(1000,state.stats[bumpStat]+gain);state.contract=Math.min(100,state.contract+8);activeApp.status="offer";state.agencyOffer={agencyId:agency.id,offeredWeek:state.week};title="面談順利，公司決定發出合約！";text=`你以${choice==="steady"?"穩健":"積極"}的方式應對問題，對方相當滿意。<b>${bumpStat}＋${gain}、簽約準備度＋8%</b>。回到經紀公司頁即可查看正式合約。`;state.flags.push({week:state.week,label:`${agency.name}面談通過`,note:`以${choice==="steady"?"穩健":"企圖心"}回答獲得合約邀約。`})}else{const gain=random(1,3);state.stats[bumpStat]=Math.min(1000,state.stats[bumpStat]+gain);activeApp.status="rejected";title="這次沒有獲得錄取通知";text=`公司婉拒了這次機會，不過臨場經驗仍有收穫，<b>${bumpStat}＋${gain}</b>。`;state.flags.push({week:state.week,label:`${agency.name}面談未獲錄取`,note:`以${choice==="steady"?"穩健":"企圖心"}回答應對，這次沒有成功。`})}state.agencyInterview=null}}
 else if(a.gains){text=`自主安排留下成果，${applyGains(a.gains)}。`;state.fatigue+=a.fatigue;state.stamina=Math.max(0,state.stamina-a.stamina)}
 else{state.fatigue+=a.fatigue;state.stamina=Math.max(0,state.stamina-a.stamina);let power=id==="audition"?(state.stats.鏡頭感+state.stats.親和力+state.stats.口才)/3:(state.stats.歌藝+state.stats.肢體表現+state.stats.社交)/3;let chance=Math.max(10,Math.min(78,32+(power-75)*.24+(state.focus==="fame"?8:0)+(choice==="safe"||choice==="steady"?10:-4)));if(Math.random()*100<chance){if(id==="audition"){const f=choice==="bold"?8:4,g=random(5,9);state.stats.鏡頭感+=g;state.fame+=f+(state.focus==="fame"?2:0);state.fans+=random(15,55);state.contract+=choice==="bold"?18:13;text=`導演請你留下資料。<b>鏡頭感＋${g}、知名度＋${f}、簽約進度＋${choice==="bold"?18:13}%</b>。`}else{const earn=choice==="interact"?random(900,1800):random(500,1100);state.money+=earn;state.fame+=2+(state.focus==="fame"?2:0);state.fans+=random(8,35);text=`有人停下來替你鼓掌。小費 <b>＋${money(earn)}</b>，知名度與粉絲也增加了。`}}else{title="這次沒有成功";success=false;const n=id==="audition"?"鏡頭感":"歌藝",g=random(1,3);state.stats[n]+=g;text=`機會擦身而過，但實戰沒有白費，<b>${n}＋${g}</b>。`}}
 state.contract=Math.min(100,state.contract);state.weekResults.push({day:DAYS[state.runnerDay],action:a.label,result:(title+" "+text.replace(/<[^>]+>/g,"")),success});
 if(state.fatigue>200){state.endingType="death";state.screen="ending";state.appOpen=null;render();return}
 if(state.fatigue>100){hospitalize();return}
 state.runnerPhase="result";state.runnerResult={title,text,success};render()}
function hospitalize(){const at=state.fatigue;state.hospitalSkipWeeks=1;state.fatigue=Math.max(0,state.fatigue-90);state.stamina=100;state.mood=Math.max(0,state.mood-5);state.flags.push({week:state.week,label:"強制住院一週",note:`疲勞升至 ${at}，健康崩潰；本週剩餘行程取消，下一週完整住院休養。`});state.reward={title:"健康亮起紅燈，強制住院一週",text:`疲勞升至 ${at}，超過負荷。本週剩餘行程已取消，接下來一週將無法排行程。`};state.history.push({week:state.week,results:[...state.weekResults],reward:false,hospitalized:true});state.screen="summary";state.appOpen=null;render()}
function finishWeek(){const train=state.schedule.filter(id=>ACTIONS[id].type==="train").length,work=state.schedule.filter(id=>["work","job"].includes(ACTIONS[id].type)).length,done=train>=2&&work>=1&&state.fatigue<=60;state.reward=done?{title:"本週任務完成！",text:"妳的準備度受到注意。獲得 $1,500，簽約進度＋10%。"}:{title:"本週任務未完成",text:"訓練、工作或疲勞條件沒有同時達成，下週還能再挑戰。"};if(done){state.money+=1500;state.contract=Math.min(100,state.contract+10)}state.history.push({week:state.week,results:[...state.weekResults],reward:done});state.screen="summary";render()}
function summaryView(){const ok=state.weekResults.filter(r=>r.success).length,nextWeek=state.week+1+state.hospitalSkipWeeks;return `<main class="summary-screen"><img src="./assets/rookie-room.webp" alt="新人房間"><section class="summary-paper"><span>WEEK ${state.week} COMPLETE</span><h1>${state.reward.title}</h1><p>${state.reward.text}</p><div class="reward-status"><div><small>順利完成</small><b>${ok}/7</b></div><div><small>現有存款</small><b>${money(state.money)}</b></div><div><small>簽約進度</small><b>${state.contract}%</b></div><div><small>目前疲勞</small><b>${state.fatigue}</b></div></div><div class="week-recap">${state.weekResults.map(r=>`<div><span>${r.day}</span><b>${r.action}</b><em>${r.success?"成功":"累積經驗"}</em></div>`).join("")}</div><button class="main-btn" id="next-week">${state.hospitalSkipWeeks?`完成一週住院休養，回到第 ${nextWeek} 週`:`回到房間，開始第 ${nextWeek} 週`} →</button></section></main>`}

function relationshipSummary(){const entries=Object.entries(state.relationships).filter(([id])=>state.knownPeople.includes(id));return entries.length?entries.map(([id,r])=>`${NPCS[id].name}｜${r.romance==="none"?"認識":r.romance}`).join("・"):"尚未建立戀愛關係"}
function endingView(){const kind=state.endingType,best=Object.entries(state.stats).sort((a,b)=>b[1]-a[1]).slice(0,3);const headline=kind==="death"?"過勞衰竭・強制結束":kind==="fiveyear"?"第五年結束・周目結算":"主動退圈";const sub=kind==="death"?"疲勞超過極限，星途在此畫下句點。正式版將依此觸發專屬結局內容。":kind==="fiveyear"?"五年時間到了，這是本輪的星途總結。":"妳選擇提前結束這一輪的追夢旅程，以下是目前為止累積的成果。";return `<main class="summary-screen"><img src="./assets/rookie-room.webp" alt="新人房間"><section class="summary-paper"><span>SEASON COMPLETE</span><h1>${headline}</h1><p>${sub}</p><div class="ending-grid"><div><small>能力最高</small><b>${best[0]?`${best[0][0]} ${best[0][1]}`:"—"}</b></div><div><small>知名度／粉絲</small><b>${state.fame}／${state.fans}</b></div><div><small>財產</small><b>${money(state.money)}</b></div><div><small>已認識人物</small><b>${state.knownPeople.length} 位</b></div><div><small>戀愛狀態</small><b>${relationshipSummary()}</b></div><div><small>重要旗標</small><b>${state.flags.length} 項</b></div></div><div class="ending-inherit"><span>下一輪入口</span><p>是否啟用「認識繼承」？只帶入曾經認識過的人物眼熟印象，不保留聯絡方式、好感或資源。</p><div class="gender-options"><button class="${state.inheritChoice?"active":""}" data-inherit="yes">啟用眼熟繼承</button><button class="${!state.inheritChoice?"active":""}" data-inherit="no">不繼承</button></div></div><button class="main-btn full" id="new-run">開始新一輪 →</button></section></main>`}
function startNewRun(){const priorKnown=[...state.knownPeople],inherit=state.inheritChoice;state=initialState();if(inherit)state.familiarNpcs=priorKnown;rollStats()}

function bind(){
 if(state.screen==="create"){document.querySelector("#player-name")?.addEventListener("input",e=>{state.name=e.target.value;document.querySelector("#to-stats").disabled=!state.name.trim()});document.querySelectorAll("[data-gender]").forEach(x=>x.onclick=()=>{const g=x.dataset.gender;state.gender=g==="自訂"?state.customGender||"自訂":g;render()});document.querySelector("#custom-gender")?.addEventListener("input",e=>{state.customGender=e.target.value;state.gender=e.target.value||"自訂"});document.querySelector("#to-stats")?.addEventListener("click",()=>{state.createStep=2;render()});document.querySelector("#back")?.addEventListener("click",()=>{state.createStep=1;render()});document.querySelector("#reroll")?.addEventListener("click",reroll);document.querySelector("#start")?.addEventListener("click",()=>{initializeHiddenStats();state.screen="game";render()});return}
 if(state.screen==="runner"){document.querySelectorAll("[data-choice]").forEach(x=>x.onclick=()=>resolveDay(x.dataset.choice));document.querySelector("#next-day")?.addEventListener("click",()=>{if(state.runnerDay===6)finishWeek();else{state.runnerDay++;startDay()}});return}
 if(state.screen==="summary"){document.querySelector("#next-week")?.addEventListener("click",()=>{if(state.hospitalSkipWeeks){state.history.push({week:state.week+1,results:[],reward:false,hospitalized:true,fullRecovery:true})}state.week+=1+state.hospitalSkipWeeks;state.hospitalSkipWeeks=0;if(state.week>260){state.endingType="fiveyear";state.screen="ending";state.reward=null;render();return}if(state.jobStage==="active"&&state.week>state.jobDeadline&&state.jobRemaining>0){state.jobStage="breached";state.jobNotice=`逾期未完成 ${state.jobRemaining} 次拍攝`}state.screen="game";state.tab="planner";state.appOpen=null;state.reward=null;render()});return}
 if(state.screen==="ending"){document.querySelectorAll("[data-inherit]").forEach(x=>x.onclick=()=>{state.inheritChoice=x.dataset.inherit==="yes";render()});document.querySelector("#new-run")?.addEventListener("click",startNewRun);return}
 document.querySelectorAll("[data-open-app]").forEach(x=>x.onclick=()=>{const target=x.dataset.openApp;if(target==="map"&&!state.drawerOpen){const openDay=state.schedule.findIndex(id=>id==="rest");if(openDay>=0)state.selectedDay=openDay}if(target==="agency"&&!state.selectedAgencyId)state.selectedAgencyId=AGENCY_LIST[0].id;state.appOpen=target;state.drawerOpen=false;render()});
 document.querySelectorAll("[data-close-app]").forEach(x=>x.onclick=()=>{state.appOpen=null;state.drawerOpen=false;render()});
 document.querySelector("[data-open-job]")?.addEventListener("click",()=>{state.appOpen="jobs";state.drawerOpen=false;render()});
 document.querySelectorAll("[data-day]").forEach(x=>x.onclick=()=>{state.selectedDay=Number(x.dataset.day);state.drawerOpen=true;render()});
 document.querySelectorAll("[data-close-drawer]").forEach(x=>x.onclick=()=>{state.drawerOpen=false;render()});
 document.querySelectorAll("[data-filter]").forEach(x=>x.onclick=()=>{state.filter=x.dataset.filter;render()});
 document.querySelectorAll("[data-pick]").forEach(x=>x.onclick=()=>{const id=x.dataset.pick;if(id==="adshoot"&&!JOB.workDays.includes(state.selectedDay)){state.notice=`此通告僅能安排在每週${jobWorkDaysText()}`;render();return}if(id==="free"){state.drawerOpen=false;state.appOpen="map";render();return}if(state.agencyInterview&&state.agencyInterview.dayIndex===state.selectedDay)releaseAgencyInterview();state.schedule[state.selectedDay]=id;state.notice=`${DAYS[state.selectedDay]}已安排「${ACTIONS[id].label}」`;state.drawerOpen=false;render()});
 document.querySelectorAll("[data-map-location]").forEach(x=>x.onclick=()=>{if(state.agencyInterview&&state.agencyInterview.dayIndex===state.selectedDay)releaseAgencyInterview();state.mapLocation=x.dataset.mapLocation;state.schedule[state.selectedDay]="free";state.notice=`${DAYS[state.selectedDay]}將前往「${MAP_LOCATIONS[state.mapLocation].name}」`;state.appOpen="planner";render()});
 document.querySelectorAll("[data-focus]").forEach(x=>x.onclick=()=>{state.focus=x.dataset.focus;state.notice=`本週策略改為「${FOCUSES[state.focus].label}」`;render()});
 document.querySelector("#copy")?.addEventListener("click",()=>{if(state.lastSchedule){if(state.agencyInterview)releaseAgencyInterview();state.schedule=state.lastSchedule.map(id=>(id==="adshoot"&&state.jobStage!=="active")||id==="agency_interview"?"rest":id);state.notice="已複製上週行程";render()}});
 document.querySelector("#rest-all")?.addEventListener("click",()=>{if(state.agencyInterview)releaseAgencyInterview();state.schedule=Array(7).fill("rest");state.notice="本週已全部改為休息";render()});
 document.querySelector("[data-go-free]")?.addEventListener("click",()=>{state.selectedDay=state.schedule.findIndex(id=>id==="rest");if(state.selectedDay<0)state.selectedDay=6;state.appOpen="map";render()});
 document.querySelectorAll("[data-select-npc]").forEach(x=>x.onclick=()=>{state.selectedNpc=x.dataset.selectNpc;render()});
 document.querySelectorAll("[data-select-agency]").forEach(x=>x.onclick=()=>{state.selectedAgencyId=x.dataset.selectAgency;render()});
 document.querySelectorAll("[data-agency-action]").forEach(x=>x.onclick=()=>{const act=x.dataset.agencyAction,id=state.selectedAgencyId||AGENCY_LIST[0].id;if(act==="apply")applyToAgency(id);if(act==="schedule-interview")scheduleAgencyInterview(id);if(act==="accept-offer")acceptAgencyOffer();if(act==="decline-offer")declineAgencyOffer();render()});
 document.querySelector("[data-retire]")?.addEventListener("click",()=>{state.endingType="retire";state.screen="ending";state.appOpen=null;render()});
 document.querySelectorAll("[data-job-action]").forEach(x=>x.onclick=()=>{const a=x.dataset.jobAction;if(a==="apply"||a==="retry"){state.jobStage="applied";state.jobNotice=""}if(a==="start-audition")state.jobStage="audition";if(a==="sign"){state.jobStage="active";state.jobNotice="合約已成立"}if(a==="schedule"){const i=state.schedule.findIndex((id,idx)=>JOB.workDays.includes(idx)&&(id==="rest"||id==="free"));if(i<0){state.notice=`本週${jobWorkDaysText()}都沒有空檔，請先移除其中一項行程`;state.appOpen="planner";render();return}state.schedule[i]="adshoot";state.selectedDay=i;state.notice=`廣告拍攝已排入${DAYS[i]}（指定工作日）`;state.appOpen="planner"}render()});
 document.querySelectorAll("[data-audition-choice]").forEach(x=>x.onclick=()=>{resolveJobAudition(x.dataset.auditionChoice);render()});
 document.querySelector("#begin-week")?.addEventListener("click",()=>{const invalidJobDay=state.schedule.findIndex((id,idx)=>id==="adshoot"&&!JOB.workDays.includes(idx));if(invalidJobDay>=0){state.notice=`${DAYS[invalidJobDay]}不是此通告的指定工作日，請重新安排`;render();return}if(budget()>state.money){state.notice="預算不足，請先調整行程";render();return}state.lastSchedule=[...state.schedule];state.weekResults=[];state.runnerDay=0;state.screen="runner";state.appOpen=null;startDay()})
}
rollStats();
